import React from 'react'
import { styleOf } from '@/lib/qpu-style'
export const QpuCard: React.FC<{ uuid: string; title: string; children?: React.ReactNode }> = ({ uuid, title, children }) => (
  <section style={{ ...styleOf(uuid), background: 'var(--qpu-surface)', color: 'var(--qpu-ink)', borderLeft: '3px solid var(--qpu-accent)', borderRadius: 'var(--qpu-radius)', padding: 'var(--qpu-gap)' }} data-uuid={uuid}>
    <h3 style={{ margin: 0, color: 'var(--qpu-accent)' }}>{title}</h3>
    {children}
  </section>
)
